SELECT FROM payments
AND status = #{status}
AND ( LOWER(payment_no) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(order_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(customer_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(provider_trade_no, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%') )
ORDER BY created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM payments
AND status = #{status}
AND ( LOWER(payment_no) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(order_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(customer_id) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(COALESCE(provider_trade_no, '')) LIKE CONCAT('%', LOWER(#{keyword}), '%') )

SELECT 
FROM payments
WHERE status = 'REQUIRES_ACTION' AND expires_at <= #{now}
ORDER BY expires_at ASC
LIMIT #{limit}
